CREATE OR REPLACE FUNCTION gx_r1(a NUMBER, b NUMBER) RETURN VARCHAR2 IS
BEGIN
  RETURN TO_CHAR(a/b) || '|' || TO_CHAR(-a);
END;
/
CREATE OR REPLACE FUNCTION gx_r2(n NUMBER) RETURN VARCHAR2 IS
  v NUMBER(5,2) := 0.5;
  d DATE := DATE '2026-03-17';
BEGIN
  RETURN TO_CHAR(v) || '|' || TO_CHAR(d);
END;
/
CREATE OR REPLACE FUNCTION gx_r3 RETURN VARCHAR2 IS
  c CHAR(5) := 'AB';
  v VARCHAR2(5) := 'AB';
  l NUMBER(5);
BEGIN
  SELECT LENGTH(code) INTO l FROM gx_codes WHERE id = 1;
  RETURN LENGTH(c) || '|' || (c || 'x') || '|' || CASE WHEN c = v THEN 'equal' ELSE 'not equal' END || '|' || l;
END;
/
CREATE OR REPLACE FUNCTION gx_r4(d DATE) RETURN VARCHAR2 IS
BEGIN
  RETURN TO_CHAR(ROUND(d, 'MM'), 'YYYY-MM-DD') || '|' || TO_CHAR(ROUND(d), 'YYYY-MM-DD');
END;
/
